practice.solution:
def ap_general(a1, a2, a3, a4, a6, p):
    n = 1
    for x in range(p):
        for y in range(p):
            lhs = y * y + a1 * x * y + a3 * y
            rhs = x ** 3 + a2 * x * x + a4 * x + a6
            if (lhs - rhs) % p == 0:
                n += 1
    return p + 1 - n

