def is_multiplicative(coeffs):
    # your code
    pass

practice.solution:
def is_multiplicative(coeffs):
    def g(a, b):
        while b:
            a, b = b, a % b
        return a
    if not coeffs or coeffs[0] != 1:
        return False
    n = len(coeffs)
    for m in range(1, n + 1):
        for k in range(1, n + 1):
            if m * k <= n and g(m, k) == 1:
                if coeffs[m * k - 1] != coeffs[m - 1] * coeffs[k - 1]:
                    return False
    return True

